#pragma once
void App::hydrideDefaultCheck(const std::string& dir){
    auto require=[](bool ok,const char* why){if(!ok)throw std::runtime_error(why);};
    shortcuts.reset();s.input.setKeymap(&shortcuts.chemistry);
    auto reset=[&](){if(textEditor.active)finishText(false);s.cancel();s.doc=Document();s.history.clear();s.selected.clear();s.input.bindDocument(s.doc.id());s.refresh();};
    auto fit=[&](){s.refresh();s.fit();invalidate();};
    auto press=[&](ObjectId id,UINT key,wchar_t character){auto point=s.view().toDevice(s.doc.atoms().get(id)->position);SendMessageW(canvas,WM_MOUSEMOVE,0,MAKELPARAM(int(point.x),int(point.y)));SendMessageW(canvas,WM_KEYDOWN,key,0);SendMessageW(canvas,WM_CHAR,character,0);SendMessageW(canvas,WM_KEYUP,key,0);};
    auto count=[&](ObjectId id){return int(s.doc.atoms().get(id)->semantics.implicitHydrogens);};
    int cases=0;
    for(int target:{8,7})for(int original:{6,target})for(int bonds:{0,1,2,3}){
        if(target==8&&bonds==3)continue;reset();ObjectId atom;s.doc.addAtom(Vec2(),original,&atom);for(int i=0;i<bonds;++i){double angle=(i-bonds*.5)*2.1;ObjectId other,edge;s.doc.addAtom(Vec2(30*cos(angle),30*sin(angle)),6,&other);s.doc.addBond(atom,other,&edge);}fit();auto before=s.doc.digest();auto atoms=s.doc.stats().aliveAtoms,edges=s.doc.stats().aliveBonds;press(atom,target==8?'O':'N',target==8?L'o':L'n');int expected=std::min(target==8?1:2,(target==8?2:3)-bonds);require(s.doc.atoms().get(atom)->element==target&&count(atom)==expected,"first hovered O/N key prefers valence-compatible hydride");require(s.doc.extensions(ObjectRef(ObjectKind::Atom,atom)).findValue("studio.hydrogens.manual"),"hydrogen count is visible");require(s.doc.stats().aliveAtoms==atoms&&s.doc.stats().aliveBonds==edges&&s.doc.stats().aliveTexts==0,"WM_CHAR is swallowed and structure stays intact");auto after=s.doc.digest();require(s.undo().ok()&&s.doc.digest()==before,"element replacement plus H count is one undo");require(s.undo(true).ok()&&s.doc.digest()==after,"hydride shortcut redo exact");++cases;
        if(bonds==1&&original==6){for(int h:(target==8?std::vector<int>{0,1}:std::vector<int>{0,1,2})){press(atom,target==8?'O':'N',target==8?L'o':L'n');require(count(atom)==h,"repeated same-element keys cycle hydrogens");}press(atom,'H',L'h');require(count(atom)==0,"H keeps cycling hydrogens without replacing element");
            press(atom,target==8?'N':'O',target==8?L'n':L'o');require(s.doc.atoms().get(atom)->element==(target==8?7:8)&&count(atom)==(target==8?2:1),"changing O to N or N to O initializes preferred hydride");
        }
    }
    for(int target:{8,7})for(auto order:{BondOrder::Double,BondOrder::Triple}){
        if(target==8&&order==BondOrder::Triple)continue;reset();ObjectId a,b,edge;s.doc.addAtom(Vec2(),6,&a);s.doc.addAtom(Vec2(30,0),6,&b);s.doc.addBond(a,b,&edge);s.doc.setBondOrder(edge,order);fit();press(a,target==8?'O':'N',target==8?L'o':L'n');require(s.doc.atoms().get(a)->element==target&&count(a)==(target==8?0:3-int(order)),"carbonyl, imine and nitrile respect bond order");++cases;
    }
    for(int ringSize:{5,6}){
        reset();std::vector<ObjectId> atoms;for(int i=0;i<ringSize;++i){ObjectId id;double angle=6.283185307179586*i/ringSize;s.doc.addAtom(Vec2(30*cos(angle),30*sin(angle)),6,&id);atoms.push_back(id);}for(int i=0;i<ringSize;++i){ObjectId edge;s.doc.addBond(atoms[i],atoms[(i+1)%ringSize],&edge);s.doc.setBondOrder(edge,BondOrder::Aromatic);s.doc.setBondSemantics(edge,BondSemantics::Aromatic);}fit();press(atoms[0],'N',L'n');s.save(dir+"/aromatic-"+std::to_string(ringSize)+".t01doc",false);require(count(atoms[0])==(ringSize==5?1:0),("aromatic ring="+std::to_string(ringSize)+" element="+std::to_string(s.doc.atoms().get(atoms[0])->element)+" H="+std::to_string(count(atoms[0]))+" status="+status).c_str());++cases;
    }
    reset();ObjectId carbon,other,edge;s.doc.addAtom(Vec2(),6,&carbon);s.doc.addAtom(Vec2(30,0),6,&other);s.doc.addBond(carbon,other,&edge);fit();press(carbon,'N',L'n');require(count(carbon)==2,"save fixture starts as NH2");require(s.save(dir+"/default-NH2.t01doc",false).ok()&&s.save(dir+"/default-NH2.cdxml",true).ok(),"save default NH2");for(auto extension:{".t01doc",".cdxml"}){Session back;require(back.open(dir+"/default-NH2"+extension).ok(),"reopen default hydride");bool found=false;for(const auto& a:back.doc.atoms().records())if(a.isAlive()&&a.element==7){found=true;require(a.semantics.implicitHydrogens==2&&back.doc.extensions(ObjectRef(ObjectKind::Atom,a.id)).findValue("studio.hydrogens.manual"),"default hydride count/display survive export");}require(found,"nitrogen retained");}
    openText(kInvalidObjectId,carbon);SetWindowTextW(edit,L"");auto before=s.doc.digest();SendMessageW(edit,WM_CHAR,L'o',0);SendMessageW(edit,WM_CHAR,L'n',0);require(textEditor.active&&textEditor.value()==L"on"&&s.doc.digest()==before,"O/N still enter ordinary text in label editor");finishText(false);fit();press(carbon,'B',L'b');require(s.doc.atoms().get(carbon)->element==35,"other element shortcuts unchanged");
    std::ofstream(dir+"/hydride-default-checks.json")<<"{\"fixtures\":"<<cases<<",\"real_hover_keydown_char\":true,\"OH_NH2_first\":true,\"same_element_bare_atom\":true,\"repeat_cycles\":true,\"H_cycle\":true,\"single_undo\":true,\"redo\":true,\"bond_order_limits\":true,\"aromatic_NH\":true,\"native_cdxml_persistence\":true,\"text_entry\":true,\"other_shortcuts\":true}";
    s.dirty=false;PostMessageW(h,WM_CLOSE,0,0);
}
